objects.customFragment:
precision mediump float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 violet;
uniform vec3 mint;
uniform float time;
varying vec2 vUv;

void main() {
  float stripe = ((sin((((vUv.y * 40.0) + (vUv.x * 10.0)) + (time * 0.8))) * 0.5) + 0.5);
  gl_FragColor = vec4(mix(violet, mint, stripe), 1.0);
}

objects.customFragmentWGSL:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  violet : vec3<f32>,
  mint : vec3<f32>,
  time : f32,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let stripe = ((sin((((in.vUv.y * 40.0) + (in.vUv.x * 10.0)) + (u.time * 0.8))) * 0.5) + 0.5);
  return vec4<f32>(mix(u.violet, u.mint, stripe), 1.0);
}

objects.customVertex:
attribute vec3 position;
attribute vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 violet;
uniform vec3 mint;
uniform float time;
varying vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

